 function cellAtPoint(x,y){if(dragging&&selectionGeometry){const geometry=selectionGeometry,position=y-(grid.getBoundingClientRect().top-geometry.top)+grid.scrollTop-geometry.scrollTop;let selected=geometry.rows[0],distance=Infinity;for(const row of geometry.rows){const next=Math.max(row.top-position,0,position-row.bottom);if(next<=distance){distance=next;selected=row;}}return selectionCells[selected?.row]?.[columnAtPoint(x)];}const rows=[...$('schedule-table').querySelectorAll('tr[data-employee-row]')];let best=null,distance=Infinity;for(const row of rows){const rect=row.getBoundingClientRect(),d=Math.max(rect.top-y,0,y-rect.bottom);if(d<distance){distance=d;best=row;}}if(!best)return null;let cell=null;distance=Infinity;for(const td of best.querySelectorAll('td[data-row]')){const rect=td.getBoundingClientRect(),d=Math.max(rect.left-x,0,x-rect.right);if(d<distance){distance=d;cell=td;}}return cell;}
